const $=s=>document.querySelector(s);
let model=null,loadError=false,step=0,records=[],activeResult=null,demo=false;
const answers={};
const fields=[
 {key:'age',label:'Age',unit:'years',type:'number',step:1,group:0,help:'Enter your age in years. This model supports ages 29–77.'},
 {key:'sex',label:'Sex on your medical record',options:[[0,'Female'],[1,'Male']],group:0,help:'Choose what is recorded on your report. These are the two categories available in the training data.'},
 {key:'cp',label:'How does your report describe chest discomfort?',options:[[1,'Typical chest-pain pattern','Typical angina'],[2,'Less typical chest-pain pattern','Atypical angina'],[3,'Other chest-pain pattern','Non-anginal pain'],[4,'No chest symptoms','Asymptomatic']],group:0,help:'Match the wording in your medical record. These are report categories, not descriptions to diagnose yourself.'},
 {key:'trestbps',label:'Blood pressure — top number',unit:'mmHg',type:'number',step:1,group:1,help:'For a resting reading of 120/80, enter 120.',report:'Look for resting systolic blood pressure. Use the measurement in your clinical record.'},
 {key:'chol',label:'Total cholesterol',unit:'mg/dL',type:'number',step:1,group:1,help:'Copy the total from your blood test. Check that the unit is mg/dL.',report:'Look for total serum cholesterol. LDL and HDL are separate readings and cannot be used here.'},
 {key:'fbs',label:'Blood sugar after fasting',options:[[0,'120 or below','mg/dL'],[1,'Above 120','mg/dL']],group:1,help:'Use your fasting blood sugar result, not a reading taken after eating.'},
 {key:'restecg',label:'Heart tracing taken at rest',options:[[0,'Normal tracing','Normal'],[1,'Changes in the tracing','ST–T wave abnormality'],[2,'Signs of thicker heart muscle','Left ventricular hypertrophy']],group:1,help:'Match the written result on your ECG report. Do not interpret the tracing yourself.'},
 {key:'thalach',label:'Highest heart rate during the exercise test',unit:'bpm',type:'number',step:1,group:2,help:'Copy the highest heart rate from your clinical exercise-test report.',report:'Look for maximum or peak heart rate (thalach). Use the measured result, not an age-based estimate or a fitness-watch reading.'},
 {key:'exang',label:'Chest discomfort during the exercise test?',options:[[0,'No'],[1,'Yes']],group:2,help:'Use the result recorded by the clinician.',report:'Look for exercise-induced angina. Answer Yes only if the report records this finding.'},
 {key:'oldpeak',label:'Change in the heart tracing with exercise',unit:'report value',type:'number',step:.1,group:2,help:'Copy the numeric ST depression (oldpeak) value from your report.',report:'This measures exercise ST depression compared with rest. It requires a clinical report; it cannot be worked out from symptoms or heart rate.'},
 {key:'slope',label:'Direction of the exercise-test tracing',options:[[1,'Rises upward','Upsloping'],[2,'Stays flat','Flat'],[3,'Slopes downward','Downsloping']],group:2,help:'Look for the ST slope at peak exercise on your report. Match the written result.'},
 {key:'ca',label:'Blood vessels visible on the scan',options:[[0,'0 vessels'],[1,'1 vessel'],[2,'2 vessels'],[3,'3 vessels']],group:2,help:'Copy the number from your clinical record.',report:'Look for ca: number of major vessels colored by fluoroscopy. This is not the number of blocked vessels. Do not guess from other scan results.'},
 {key:'thal',label:'Blood-flow scan result',options:[[3,'Normal blood flow','Normal'],[6,'Reduced flow at rest and with exercise','Fixed defect'],[7,'Reduced flow with exercise that improves at rest','Reversible defect']],group:2,help:'Match the result on your nuclear stress-test report.',report:'Look for the thallium stress-test result (thal). This is a heart blood-flow scan, not a test for thalassemia.'}
];
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percent=x=>(100*x).toFixed(1)+'%';
const labels=Object.fromEntries(fields.map(f=>[f.key,f.label]));
function shownValue(key,value){const f=fields.find(f=>f.key===key);return f.options?f.options.find(o=>o[0]===Number(value))?.[1]||'Unknown':`${value} ${f.unit}`;}
function field(f){
 const val=answers[f.key]??'';
 const help=`<p class="field-help" id="help-${f.key}">${f.help}</p>${f.report?`<details class="report-help"><summary>Where to find this on my report</summary><p>${f.report}</p></details>`:''}`;
 if(f.type==='number'){
  const range=model.ranges[f.key];
  return `<div class="field"><label for="${f.key}">${f.label}</label><div class="input-wrap"><input type="number" name="${f.key}" id="${f.key}" min="${range[0]}" max="${range[1]}" step="${f.step}" value="${esc(val)}" inputmode="${f.step===1?'numeric':'decimal'}" required aria-describedby="help-${f.key}" placeholder="${range[0]}–${range[1]}"><span>${f.unit}</span></div>${help}</div>`;
 }
 return `<fieldset class="field option-field full-width" id="${f.key}" tabindex="-1" aria-describedby="help-${f.key}"><legend>${f.label}</legend>${help}<div class="option-grid ${f.options.length===3?'three-options':''}">${f.options.map(([v,label,term])=>`<label class="option-card"><input type="radio" name="${f.key}" value="${v}" ${String(val)===String(v)?'checked':''}><span><strong>${label}</strong>${term?`<small>${f.key==='fbs'?'':'On report: '}${term}</small>`:''}</span></label>`).join('')}</div><label class="unknown-choice"><input type="radio" name="${f.key}" value="" ${Object.hasOwn(answers,f.key)&&val===''?'checked':''}><span>I’m not sure / I don’t have this result</span></label><p class="unknown-help" ${val===''&&Object.hasOwn(answers,f.key)?'':'hidden'}>You’ll need this result to run a prediction. You can try the fictional sample below to explore the app.</p></fieldset>`;
}
function capture(){new FormData($('#assessmentForm')).forEach((v,k)=>answers[k]=v);}
function renderForm(){
 activeResult=null;$('#result')?.remove();$('#assessmentForm').hidden=false;$('.steps').hidden=false;$('#stepCount').hidden=false;$('#stepCount').textContent=`Step ${step+1} of 3`;
 document.querySelectorAll('.step').forEach((el,i)=>{el.classList.toggle('active',i===step);el.classList.toggle('done',i<step);if(i===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});
 $('#backBtn').hidden=step===0;$('#formError').textContent='';$('#continueBtn').hidden=false;$('#continueBtn').disabled=!model;$('#continueBtn').innerHTML=`${step===2?'Run prediction':'Continue'} <svg><use href="#i-arrow"/></svg>`;$('#stepHint').textContent=['Use clinical report values.','Check your units carefully.','All 13 inputs are required.'][step];
 if(!model){$('#formContent').innerHTML=loadError?'<div class="emergency"><h3>The model could not be loaded.</h3><p>No prediction is available. Please reload this page to try again.</p></div>':'<p class="form-subtitle" role="status">Loading the trained model…</p>';return;}
 const titles=['Let’s start with a little about you.','Add your blood pressure and blood tests.','Match the results on your heart-test reports.'];
 const subtitles=['Keep your medical reports handy. Choose the answer that matches your record.','The examples below help you find the right numbers. Check the units before entering them.','Each choice shows everyday wording and the term used on your report. Missing a result? Try the fictional sample. Do not arrange tests just to use this app.'];
 $('#formContent').innerHTML=`${demo?'<div class="demo-banner">FICTIONAL SAMPLE · These are example values, not your health data.</div>':''}<h3 class="form-heading">${titles[step]}</h3><p class="form-subtitle">${subtitles[step]}</p><div class="field-grid">${fields.filter(f=>f.group===step).map(field).join('')}</div>${step===0?`<fieldset class="safety-box question"><legend class="question-label">Symptoms right now?</legend><p>Are you having new or unexplained chest discomfort, trouble breathing, fainting, or pain spreading to your arm, jaw, or back?</p><div class="radio-group">${[['no','No, none of these'],['yes','Yes / I’m unsure']].map(([v,l])=>`<label class="choice"><input type="radio" name="symptoms" value="${v}" ${answers.symptoms===v?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset><div id="symptomWarning"></div>`:''}<div class="requirements-note">Missing a report value? Prediction requires all 13 inputs. You can <button type="button" class="text-btn" data-demo>try a fictional sample</button> instead.</div>`;
 updateEmergency();
}
function updateEmergency(){const urgent=answers.symptoms==='yes';$('#continueBtn').disabled=urgent||!model;$('#continueBtn').hidden=urgent;const warning=$('#symptomWarning');if(warning)warning.innerHTML=urgent?'<div class="emergency" role="alert"><h3>Seek emergency help now.</h3><p>Contact your local emergency services immediately, even if you are unsure. Do not wait for a model result or drive yourself. This tool cannot rule out an emergency.</p></div>':'';}
function formChanged(){capture();$('#formError').textContent='';document.querySelectorAll('.option-field').forEach(el=>{el.querySelector('.unknown-help').hidden=!(Object.hasOwn(answers,el.id)&&answers[el.id]==='');});updateEmergency();}
$('#assessmentForm').addEventListener('input',formChanged);$('#assessmentForm').addEventListener('change',formChanged);
function errorText(e){if(e.reason==='missing')return `Please complete “${labels[e.key]}”. If you don’t have this result, try the fictional sample instead.`;if(e.reason==='range')return `${labels[e.key]} is outside the dataset range (${e.min}–${e.max}). This model does not support that value. Check the units; do not change a real reading to fit the model.`;if(e.reason==='integer')return `${labels[e.key]} must be a whole number.`;return `Please choose a valid ${labels[e.key].toLowerCase()}.`;}
$('#assessmentForm').addEventListener('submit',e=>{e.preventDefault();capture();if(!model||answers.symptoms==='yes'){updateEmergency();return;}
 const keys=fields.filter(f=>f.group===step).map(f=>f.key);const errs=PulsePredictor.validate(model,answers).filter(e=>keys.includes(e.key));
 if(errs.length){$('#formError').textContent=errorText(errs[0]);$('#'+errs[0].key)?.focus({preventScroll:true});return;}
 if(step===0&&!answers.symptoms){$('#formError').textContent='Please answer the current-symptom check.';return;}
 if(step<2){step++;renderForm();scrollCard();}else runPrediction();
});
$('#backBtn').onclick=()=>{capture();step--;renderForm();scrollCard();};
function scrollCard(){$('#assessmentCard').scrollIntoView({behavior:'smooth',block:'start'});}
function runPrediction(){
 const errors=PulsePredictor.validate(model,answers);if(errors.length){$('#formError').textContent=errorText(errors[0]);return;}
 if(answers.symptoms!=='no')return;
 const prediction=PulsePredictor.predict(model,answers);const result={id:Date.now(),date:new Date(),inputs:Object.fromEntries(fields.map(f=>[f.key,Number(answers[f.key])])),demo,version:model.version,...prediction};records.unshift(result);showResult(result);scrollCard();
}
function demoPrediction(){if(!model)return;Object.assign(answers,{age:55,sex:1,cp:4,trestbps:140,chol:260,fbs:0,restecg:1,thalach:125,exang:1,oldpeak:2,slope:2,ca:1,thal:7,symptoms:'no'});demo=true;navigate('assessment');runPrediction();}
function showResult(r){
 activeResult=r;$('#assessmentForm').hidden=true;$('.steps').hidden=true;$('#stepCount').hidden=true;$('#result')?.remove();const host=document.createElement('div');host.id='result';$('#assessmentCard').append(host);
 const max=Math.max(...r.contributions.map(c=>Math.abs(c.value)),.01);
 host.innerHTML=`${r.demo?'<div class="demo-banner">FICTIONAL SAMPLE RESULT · Not a prediction about you.</div>':''}<p class="result-date">${esc(r.date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))} · ${esc(r.version)}</p><h2 class="result-title">Your model result.</h2><p class="result-intro">The model classifies this clinical profile against coronary disease labels in the Cleveland dataset.</p><div class="prediction-output ${r.positive?'positive':'negative'}"><div><span class="eyebrow">POSITIVE-CLASS MODEL SCORE</span><strong class="prediction-score">${percent(r.score)}</strong><span class="prediction-label">${r.positive?'Disease class predicted':'No-disease class predicted'}</span></div><div class="score-ring" style="--score:${r.score*100}%"><svg><use href="#i-pulse"/></svg></div></div><p class="score-explainer">Classification threshold: 50%. This score is <strong>not a clinically validated probability</strong> that you have disease. It does not estimate future risk.</p><div class="result-caution"><strong>${r.positive?'A positive output is not a diagnosis.':'A negative output cannot rule out disease.'}</strong><p>False results occur. Only a clinician can interpret your test findings and diagnose coronary disease. Do not start, stop, or change medication based on this output.</p></div><h3 class="result-section-title">What influenced the model?</h3><p class="form-subtitle">Largest contributions compared with the training-data average. These explain the model’s calculation, not medical causes.</p><div class="contributions">${r.contributions.slice(0,5).map(c=>`<div class="contribution"><div><span>${labels[c.key]}</span><strong class="${c.value>=0?'toward':'away'}">${c.value>=0?'↑ Toward disease class':'↓ Away from disease class'}</strong></div><div class="contribution-track"><span class="${c.value>=0?'toward':'away'}" style="width:${Math.max(2,100*Math.abs(c.value)/max)}%"></span></div><small>${esc(shownValue(c.key,r.inputs[c.key]))} · ${c.value>=0?'+':''}${c.value.toFixed(2)} log-odds contribution</small></div>`).join('')}</div><details class="inputs-detail"><summary>Review all 13 input values</summary><dl>${fields.map(f=>`<div><dt>${f.label}</dt><dd>${esc(shownValue(f.key,r.inputs[f.key]))}</dd></div>`).join('')}</dl></details><div class="model-result-metrics"><span><strong>${percent(model.metrics.accuracy)}</strong>Holdout accuracy</span><span><strong>${model.training.testRows}</strong>Test records</span><span><strong>${model.metrics.confusion.falseNegative}</strong>Missed disease cases</span></div><p class="source-note">One small internal test split; no external clinical validation. <button class="text-btn" data-page="model">See full evaluation and limitations ↗</button></p><p class="source-note">New chest discomfort, trouble breathing, or other possible heart attack symptoms? Contact local emergency services immediately regardless of this result.</p><div class="results-actions"><button class="primary" id="downloadBtn"><svg><use href="#i-download"/></svg>Download prediction</button><button class="secondary" id="editBtn">Edit inputs</button><button class="text-btn" id="restartBtn">New prediction</button></div>`;
 $('#downloadBtn').onclick=()=>download(r);$('#editBtn').onclick=()=>{Object.assign(answers,r.inputs,{symptoms:'no'});demo=r.demo;step=0;renderForm();scrollCard();};$('#restartBtn').onclick=restart;
}
function restart(){Object.keys(answers).forEach(k=>delete answers[k]);demo=false;step=0;renderForm();scrollCard();}
function download(r){const text=`PULSE — EXPERIMENTAL CORONARY DISEASE PREDICTION\n${r.date.toLocaleString()}\nModel: ${r.version}\n${r.demo?'FICTIONAL SAMPLE — NOT YOUR HEALTH DATA\n':''}\nMODEL RESULT\nPositive-class score: ${percent(r.score)}\nPredicted dataset class: ${r.positive?'Disease':'No disease'}\nDecision threshold: 50%\n\nThis is NOT a clinical diagnosis, a calibrated personal disease probability, or an estimate of future risk. A negative result cannot rule out disease. Do not change treatment or delay care based on this result.\n\nINPUTS\n${fields.map(f=>f.label+': '+shownValue(f.key,r.inputs[f.key])).join('\n')}\n\nMODEL EVALUATION\n${model.training.trainRows} training records; ${model.training.testRows} held-out records.\nAccuracy: ${percent(model.metrics.accuracy)}; AUROC: ${model.metrics.rocAuc.toFixed(3)}\nSensitivity: ${percent(model.metrics.sensitivity)}; specificity: ${percent(model.metrics.specificity)}\nConfusion matrix: ${JSON.stringify(model.metrics.confusion)}\n\nLIMITATIONS\n${model.limitations.join('\n')}\n\nFor new or unexplained chest discomfort, trouble breathing, or other possible heart attack symptoms, contact local emergency services immediately.\n\nDATA CREDIT\n${model.source.citation}\n${model.source.doi}\nLicense: ${model.source.license}\n\nYour health inputs were processed in this tab. This file contains the entered values; store it privately.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`pulse-prediction-${r.date.toISOString().slice(0,10)}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Prediction report ready to save.');}
function renderModel(){if(!model){$('#modelContent').innerHTML='<p>Model details are unavailable until the model loads.</p>';return;}const m=model.metrics,c=m.confusion,t=model.training;
 $('#modelContent').innerHTML=`<div class="model-header-card"><span class="pill">${model.version}</span><h2>Logistic regression. Real training data.</h2><p>Five numeric inputs are standardized; eight categorical inputs are one-hot encoded. A trained, regularized logistic regression combines them into a binary classification. The exact same fitted model is used for the evaluation below and for every prediction in this app.</p><div class="model-stats"><div><b>${t.trainRows}</b><span>Training records</span></div><div><b>${t.testRows}</b><span>Held-out test records</span></div><div><b>13</b><span>Clinical inputs</span></div></div></div><div class="metric-grid"><article><b>${percent(m.accuracy)}</b><h3>Accuracy</h3><p>Correct predictions on the test set. 95% Wilson interval: ${percent(m.accuracyCI95[0])}–${percent(m.accuracyCI95[1])}.</p></article><article><b>${percent(m.sensitivity)}</b><h3>Sensitivity</h3><p>Disease-class records identified. ${c.falseNegative} of ${c.falseNegative+c.truePositive} disease records were missed.</p></article><article><b>${percent(m.specificity)}</b><h3>Specificity</h3><p>No-disease records identified. ${c.falsePositive} of ${c.falsePositive+c.trueNegative} no-disease records were flagged.</p></article><article><b>${m.rocAuc.toFixed(3)}</b><h3>ROC AUC</h3><p>Ranking discrimination on this test split. It does not establish clinical reliability.</p></article></div><div class="model-info-grid"><article class="library-card"><h2>How the test was run</h2><p>From ${t.sourceRows} records, ${t.excludedRows} with missing fields were excluded. ${t.completeRows} complete cases were split ${t.split}, with seed ${t.randomSeed}. Preprocessing was fitted on training records only. No threshold or hyperparameter was selected using the test set; the threshold is fixed at 0.5.</p><p>Majority-class baseline: ${percent(m.majorityBaselineAccuracy)} accuracy. Brier score: ${m.brier.toFixed(3)}. The model was not refitted on the test records after evaluation.</p></article><article class="library-card"><h2>Every error, visible.</h2><table class="confusion-table"><caption>Held-out confusion matrix · ${t.testRows} records</caption><thead><tr><th scope="col">Actual label</th><th scope="col">Predicted no disease</th><th scope="col">Predicted disease</th></tr></thead><tbody><tr><th scope="row">No disease</th><td>${c.trueNegative}</td><td>${c.falsePositive}</td></tr><tr><th scope="row">Disease</th><td>${c.falseNegative}</td><td>${c.truePositive}</td></tr></tbody></table></article></div><article class="library-card model-limitations"><h2>Where this model stops.</h2><ul>${model.limitations.map(l=>`<li>${l}</li>`).join('')}</ul><p>The target is coronary angiographic disease status (source label num &gt; 0 versus num = 0), not every form of heart disease. The training set contains ${t.trainFemale} female-coded and ${t.trainMale} male-coded records. Performance by sex, age group, ethnicity, and geography has not been established.</p></article><article class="library-card model-source"><h2>Reproducible, not mysterious.</h2><p>${model.source.citation} Licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Pulse transforms the data into an independently trained model; the dataset authors do not endorse this app.</p><div class="results-actions"><a class="secondary" href="https://archive.ics.uci.edu/dataset/45/heart+disease" target="_blank" rel="noopener">View original dataset ↗</a><a class="secondary" href="model.json" download>Download model &amp; metrics</a><a class="secondary" href="training-source.zip" download>Download training source</a></div></article>`;
}
function renderHistory(){$('#historyContent').innerHTML=records.length?records.map((r,i)=>`<article class="history-card"><div><h3>${r.demo?'Fictional sample':'Clinical-input'} prediction</h3><p>${esc(r.date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))} · ${percent(r.score)} model score · ${r.positive?'Disease class':'No-disease class'}</p></div><button class="secondary" data-result="${i}">View prediction →</button></article>`).join('')+'<p class="history-privacy">Available only in this tab. Download a report before reloading or closing. These outputs are not clinical diagnoses.</p>':`<div class="empty-card"><span class="icon-box"><svg><use href="#i-pulse"/></svg></span><h2>Your predictions will appear here.</h2><p>Enter clinical report values or try a fictional sample to explore the model.</p><button class="primary" data-page="assessment">Start prediction →</button></div>`;}
function navigate(page){if(!['assessment','history','learn','model'].includes(page))page='assessment';document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==`page-${page}`);document.querySelectorAll('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb').textContent={assessment:'Overview',history:'My predictions',learn:'Heart health library',model:'Model & accuracy'}[page];if(page==='history')renderHistory();if(page==='model')renderModel();window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){history.replaceState(null,'','#'+nav.dataset.page);navigate(nav.dataset.page);}if(e.target.closest('[data-demo]'))demoPrediction();const r=e.target.closest('[data-result]');if(r){history.replaceState(null,'','#assessment');navigate('assessment');showResult(records[Number(r.dataset.result)]);scrollCard();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
$('#startBtn').onclick=()=>{if(activeResult)restart();else scrollCard();};$('#demoBtn').onclick=demoPrediction;
$('#privacyBtn').onclick=()=>$('#privacyDialog').showModal();$('#closePrivacy').onclick=$('#privacyOk').onclick=()=>$('#privacyDialog').close();
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
$('#clearBtn').onclick=()=>{records=[];restart();renderHistory();toast('Your session data has been cleared.');};
$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'long'});
renderForm();navigate(location.hash.slice(1));$('#demoBtn').disabled=true;
fetch('model.json').then(r=>{if(!r.ok)throw new Error('Model unavailable');return r.json();}).then(data=>{if(data.version!=='pulse-cleveland-lr-1.0.0'||data.weights.length!==28)throw new Error('Unsupported model');model=data;$('#demoBtn').disabled=false;renderForm();renderModel();}).catch(()=>{loadError=true;renderForm();});
